/**
 * ROW-ACTIONS CELL — the guaranteed trailing "Update" utility column.
 *
 * Previously nothing guaranteed a row action in VIEW mode: the config column
 * `update` (later renamed `actions`) only ever rendered if the user's saved
 * view carried its key — with the stored default view and every preset
 * omitting it, the Update action column was unreachable on the master list
 * (see the DELIVERABLES note). This cell is generated by the grid builder for
 * EVERY view, pinned to the right edge of the scrollport, and excluded from
 * exports by type.
 *
 * Contract (Task C §2):
 *  • primary Update (38px hit area) — hover/150 ms focus prefetch, opens the
 *    Quick View directly in Edit mode on the section matching the view;
 *  • ⋯ "More actions" menu (Radix DropdownMenu → portal, NOT per-row) with
 *    Open full profile / View history / Print / Export;
 *  • "Saved ✓" flash for 1.5 s at a FIXED width (never reflows the row);
 *  • a small Draft dot while a saved draft exists;
 *  • Viewers see a View (eye) button and a menu without the Edit items;
 *  • click never triggers the row's quick-view handler (stopPropagation),
 *    never toggles the checkbox;
 *  • keyboard: Enter/Space on the button; U on the row (delegated in
 *    MasterGridRow); Shift+F10 / Menu key opens the ⋯ menu.
 */

import {
  useEffect,
  useRef,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
} from "react";
import {
  Check,
  Eye,
  ExternalLink,
  History,
  MoreHorizontal,
  Pencil,
  Printer,
  Sheet,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { MasterRow } from "@/lib/masterColumns";

export type RowActionsProps = {
  /** Viewers (role "viewer") see View, never Update or Save. */
  canEdit: boolean;
  isAdmin?: boolean;
  /** Admin "Button label": Update / Edit. Default "Update". */
  label?: string;
  /** Quick View, Edit mode, section-matched. */
  onUpdate?: (row: MasterRow) => void;
  /** The full facility profile route. */
  onOpenProfile?: (row: MasterRow) => void;
  /** The shared audit/history view. */
  onViewHistory?: (row: MasterRow) => void;
  /** The facility sheet (existing profile PDF writer). */
  onPrint?: (row: MasterRow) => void;
  /** One-facility PDF / Excel export (existing paths). */
  onExport?: (row: MasterRow, format: "pdf" | "excel") => void;
  /** Unsigned hover/focus prefetch (the page owners it). */
  onPrefetch?: (row: MasterRow) => void;
  /** facilityIds whose save completed < 1.5 s ago — "Saved ✓". */
  savedIds?: ReadonlySet<string>;
  /** Facility has a saved local quick-view draft (Draft dot on the button).
   *  Page-level Set — never a per-row localStorage read. */
  draftIds?: ReadonlySet<string>;
  /** Admin "Compact icon-only below 1280 px" (default ON) ∧ a narrow window:
   *  the labelled button collapses to its icon, the aria-label and tooltip
   *  keep the full name. The column width never changes. */
  compact?: boolean;
};

/** The control that opened the Quick View — focus returns here on close. */
let lastTrigger: HTMLElement | null = null;

export function focusLastRowActionTrigger(): void {
  const el = lastTrigger;
  if (!el || !el.isConnected) return;
  el.focus({ preventScroll: true });
}

/** Opening the Quick View with cached rows costs <100ms; the full record
 *  prefetch is debounced here (Task C §5: 100ms) so a fast pointer across
 *  many rows never fires the profile query 20 times. */
function usePrefetch(handlers: RowActionsProps, row: MasterRow) {
  const timer = useRef<number | null>(null);
  const fire = () => {
    if (timer.current != null) return;
    timer.current = window.setTimeout(() => {
      timer.current = null;
      handlers.onPrefetch?.(row);
    }, 100);
  };
  useEffect(
    () => () => {
      if (timer.current != null) {
        window.clearTimeout(timer.current);
        timer.current = null;
      }
    },
    [],
  );
  return fire;
}

export function RowActionsCell({
  row,
  canEdit,
  isAdmin = false,
  label = "Update",
  onUpdate,
  onOpenProfile,
  onViewHistory,
  onPrint,
  onExport,
  onPrefetch,
  savedIds,
  draftIds,
  compact = false,
}: RowActionsProps & { row: MasterRow }) {
  const justSaved = !!savedIds?.has(String(row.facility._id));
  const hasDraft = !!draftIds?.has(String(row.facility._id));
  const prefetch = usePrefetch(
    { canEdit, isAdmin, label, onUpdate, onOpenProfile, onViewHistory, onPrint, onExport, onPrefetch, compact },
    row,
  );
  const name = row.facility.name;
  return (
    <div
      data-testid="row-actions"
      className="row-actions relative flex h-full w-full items-center justify-center gap-1"
      onClick={(e) => e.stopPropagation()}
      onKeyDown={(e) => {
        if (e.key === "Escape") e.stopPropagation();
      }}
    >
      <Button
        size="sm"
        variant={canEdit ? "default" : "outline"}
        // The LABEL slot is a fixed width, so "Update" → "Edit" → "Saved ✓"
        // never changes the button's width (the 132px column never reflows).
        className={cn(
          "row-actions-btn h-8 shrink-0 gap-1 px-1 text-xs",
          // Compact keeps a 36px hit area (icon only).
          compact ? "w-9 px-0" : "",
        )}
        disabled={justSaved} // "Saved ✓" never acts, and never reflows
        aria-label={`${canEdit ? label : "View"} ${name}`}
        data-tip={
          canEdit
            ? `${label} ${name} — opens the quick view in Edit mode`
            : `View ${name} — opens the quick view`
        }
        onClick={(e: ReactMouseEvent<HTMLButtonElement>) => {
          e.stopPropagation();
          if (justSaved) return;
          lastTrigger = e.currentTarget;
          if (canEdit) onUpdate?.(row);
          else onOpenProfile?.(row);
        }}
        onMouseEnter={prefetch}
        onFocus={prefetch}
        onKeyDown={(e: ReactKeyboardEvent<HTMLButtonElement>) => {
          // Radix already handles Enter/Space; the menu key opens ⋯ too.
          if ((e.shiftKey && e.key === "F10") || e.key === "ContextMenu") {
            const more =
              e.currentTarget.parentElement?.querySelector<HTMLElement>(
                "[data-more-actions]",
              );
            if (more) {
              e.preventDefault();
              e.stopPropagation();
              more.click();
            }
          }
        }}
        data-testid="row-actions-btn"
      >
        <DraftDot show={hasDraft} />
        {justSaved ? (
          compact ? (
            <>
              <Check className="size-3.5" aria-hidden />
              <span className="sr-only">Saved</span>
            </>
          ) : (
            <span
              className="row-actions-saved w-[52px] text-center whitespace-nowrap"
              aria-live="polite"
            >
              Saved ✓
            </span>
          )
        ) : canEdit ? (
          <>
            <Pencil className="size-3.5" aria-hidden />
            {compact ? null : (
              <span className="row-actions-label w-[52px] text-center">{label}</span>
            )}
          </>
        ) : (
          <>
            <Eye className="size-3.5" aria-hidden />
            {compact ? null : (
              <span className="row-actions-label w-[52px] text-center">View</span>
            )}
          </>
        )}
      </Button>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="row-actions-more size-6 shrink-0 text-muted-foreground hover:text-foreground"
            aria-label={`More actions ${name}`}
            data-tip="More actions"
            data-testid="row-actions-more"
            data-more-actions=""
            onClick={(e) => e.stopPropagation()}
            onMouseEnter={prefetch}
            onFocus={prefetch}
          >
            <MoreHorizontal className="size-4" aria-hidden />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          onClick={(e) => e.stopPropagation()}
          className="min-w-52"
        >
          <DropdownMenuLabel className="text-xs text-muted-foreground">
            {name}
          </DropdownMenuLabel>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            onSelect={() => onOpenProfile?.(row)}
            aria-label={`Open full profile ${name}`}
          >
            <ExternalLink className="size-4" aria-hidden /> Open full profile
          </DropdownMenuItem>
          {onViewHistory && (
            <DropdownMenuItem onSelect={() => onViewHistory(row)}>
              <History className="size-4" aria-hidden /> View history
            </DropdownMenuItem>
          )}
          {onPrint && (
            <DropdownMenuItem onSelect={() => onPrint(row)}>
              <Printer className="size-4" aria-hidden /> Print facility sheet
            </DropdownMenuItem>
          )}
          {onExport && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onSelect={() => onExport(row, "pdf")}>
                <Sheet className="size-4" aria-hidden /> Export this facility (PDF)
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onExport(row, "excel")}>
                <Sheet className="size-4" aria-hidden /> Export this facility (Excel)
              </DropdownMenuItem>
            </>
          )}
          {/* Role-aware: no edit items for viewers. */}
          {!canEdit && (
            <p className="px-2 pt-2 text-[11px] text-muted-foreground">
              Your role can view facilities but not edit them.
            </p>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

/** One tiny Draft dot: a saved local quick-view draft exists for this row
 *  (the page computes it — never a per-row localStorage read). */
function DraftDot({ show }: { show: boolean }) {
  if (!show) return null;
  return (
    <span
      role="status"
      aria-label="Saved draft"
      data-tip="A draft is saved for this facility"
      data-testid="row-draft-dot"
      className="absolute -right-0.5 -top-0.5 z-10 size-2 rounded-full bg-amber-500 ring-1 ring-background"
    />
  );
}
